  .rx-node-box { fill:#ffffff; stroke:#cbd8cc; stroke-width:1.2; }
  .rx-node-source .rx-node-box { fill:#f0f7f0; }
  .rx-node-sink .rx-node-box { fill:#eaf5f0; }
